            k=a.get('type') if isinstance(a,dict) else str(type(a))
            kinds[k]+=1
            s=json.dumps(a,ensure_ascii=False)
            if k not in samples or len(s)>len(samples[k][1]): samples[k]=(lab,s)
        # system-reminder texts inside tool results or user content
        s=line
        for m in re.finditer(r'<system-reminder>(.*?)</system-reminder>', s, re.S):
            t=m.group(1)[:80]
            key=re.sub(r'\d+','N',t)[:60]
            rem[key]+=1
            remsamples.setdefault(key,(lab,m.group(1)[:400]))
print(kinds)
